//: 機微フィールド保存時暗号化 (生成時 標準装備)
// マイナンバー・口座番号など、漏洩時の影響が大きいカラム値を AES-256-GCM で
// 暗号化して DB へ保存するヘルパ。個人情報保護法の安全管理措置 (暗号化) に対応。
//
// 鍵: 環境変数 FIELD_ENCRYPTION_KEY (32 byte の base64)。発行例:
//   node -e "console.log(require('crypto').randomBytes(32).toString('base64'))"
// 保存形式: enc:v1:<iv b64>:<authTag b64>:<ciphertext b64>

import crypto from 'crypto';

function getKey(): Buffer {
  const raw = process.env.FIELD_ENCRYPTION_KEY;
  if (!raw) {
    throw new Error('FIELD_ENCRYPTION_KEY が設定されていません (.env に 32byte base64 を発行してください)');
  }
  const key = Buffer.from(raw, 'base64');
  if (key.length !== 32) {
    throw new Error('FIELD_ENCRYPTION_KEY は 32byte の base64 である必要があります');
  }
  return key;
}

export function encryptField(plaintext: string): string {
  if (!plaintext) return plaintext;
  const iv = crypto.randomBytes(12);
  const cipher = crypto.createCipheriv('aes-256-gcm', getKey(), iv);
  const enc = Buffer.concat([cipher.update(plaintext, 'utf8'), cipher.final()]);
  const tag = cipher.getAuthTag();
  return ['enc', 'v1', iv.toString('base64'), tag.toString('base64'), enc.toString('base64')].join(':');
}

export function decryptField(stored: string): string {
  if (!stored || !stored.startsWith('enc:v1:')) return stored; // 平文互換 (移行期間)
  const [, , ivB64, tagB64, dataB64] = stored.split(':');
  const decipher = crypto.createDecipheriv('aes-256-gcm', getKey(), Buffer.from(ivB64, 'base64'));
  decipher.setAuthTag(Buffer.from(tagB64, 'base64'));
  return Buffer.concat([decipher.update(Buffer.from(dataB64, 'base64')), decipher.final()]).toString('utf8');
}

/** 検索用の決定的ハッシュ (暗号化カラムの完全一致検索に使う / 元値復元は不可) */
export function hashFieldForLookup(plaintext: string): string {
  return crypto.createHmac('sha256', getKey()).update(plaintext.toLowerCase().trim()).digest('hex');
}
